class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def KDistanceNodes(root, target, k):
    def build_graph(node, parent=None):
        if node is None:
            return
        if parent:
            graph[node] = graph.get(node, []) + [parent]
            graph[parent] = graph.get(parent, []) + [node]
        build_graph(node.left, node)
        build_graph(node.right, node)

    def find_target(node, target):
        if node is None:
            return None
        if node.val == target:
            return node
        left = find_target(node.left, target)
        if left:
            return left
        return find_target(node.right, target)

    graph = {}
    build_graph(root)
    target_node = find_target(root, target)
    if not target_node:
        return []

    queue = [(target_node, 0)]
    visited = set([target_node])
    result = []

    while queue:
        current, distance = queue.pop(0)
        if distance == k:
            result.append(current.val)
            continue
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, distance + 1))

    return sorted(result)
